"""Gate 1 detection (engine-legality.md section 5; engine-to-kit-handoff.md section 4): each planted violation P1-P4, generated by inject_generated.py on a
changed copy of the engine, must turn exactly its named verdict line to FAIL in check_generated.py and no other line; a crash, a missing file or a failure
elsewhere is NOT DETECTED. Exit 1 unless all four are detected and the unmodified control passes."""
import subprocess, sys, os, re
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "product"), PYTHONDONTWRITEBYTECODE="1")
EXPECT = {"P1": "possessions unexplained 0", "P2": "downs OTHER 0", "P3": "stopped clock: no STOP stretch falls more than the play plus 1 s", "P4": "season rule: kickoff touchback spot == quoted (30)"}
def verdict(args):
    p = subprocess.run([sys.executable, os.path.join(ROOT, "checks", "check_generated.py"), "2024", "15", "0"] + args, env=env, capture_output=True, text=True, cwd=ROOT)
    lines = dict(re.findall(r"^  (.+?): (PASS|FAIL)$", p.stdout, re.M)); return lines, p.returncode, (p.stderr or "")[-400:]
ok = True
lines, rc, err = verdict([]); control = bool(lines) and all(v == "PASS" for v in lines.values())
print(f"gate 1 control (unmodified draw 0): {len(lines)} lines, all PASS {control}" + ("" if control else f" | {lines} {err}")); ok &= control
for F, want in EXPECT.items():
    g = subprocess.run([sys.executable, os.path.join(ROOT, "checks", "inject_generated.py"), F], env=env, capture_output=True, text=True, cwd=ROOT)
    if g.returncode != 0: print(f"  {F}: generation failed -> NOT DETECTED | {(g.stderr or g.stdout)[-300:]}"); ok = False; continue
    lines, rc, err = verdict([F]); failed = sorted(k for k, v in lines.items() if v == "FAIL")
    detected = failed == [want]
    print(f"  {F}: expected FAIL only on [{want}] | failed {failed} -> {'DETECTED' if detected else 'NOT DETECTED'}" + ("" if lines else f" | no verdict lines {err}")); ok &= detected
print("GATE 1 PLANTS:", "PASS" if ok else "FAIL"); sys.exit(0 if ok else 1)
